```javascript
const axios = require("axios");

async function getDownloadInfo(url) {
  try {
    const response = await axios.get(url);
    return response.data;
  } catch (error) {
    return {
      error: error.message
    };
  }
}

const apiUrl = "https://a.ymcdn.org/api/v1/convert?sig=24zr7FbPp7HAsv2vO9VzYBM8W4PHp3JOvroVLmBgZOpFmPNwO65jydFNoZbCFaq1WRZjbDYn&v=Ys7-6_t7OEQ&f=mp3&_=0.7395039949559807";

getDownloadInfo(apiUrl)
  .then(result => m.reply(JSON.stringify(result, null, 2)))
  .catch(error => m.reply(error.message));
```
